using System.Globalization;
using System.Text.RegularExpressions;

public readonly record struct Money(long Cents, string Currency)
{
    public static Money Parse(string text)
    {
        var m = Regex.Match(text.Trim(), @"^(-?)(\d+)(?:\.(\d{1,2}))?\s+([A-Z]{3})$");
        if (!m.Success) throw new FormatException($"not an amount of money: {text}");
        long whole = long.Parse(m.Groups[2].Value, CultureInfo.InvariantCulture);
        long cents = m.Groups[3].Success ? long.Parse(m.Groups[3].Value.PadRight(2, '0'), CultureInfo.InvariantCulture) : 0;
        long total = whole * 100 + cents;
        return new Money(m.Groups[1].Value == "-" ? -total : total, m.Groups[4].Value);
    }

    private void SameCurrency(Money other)
    {
        if (other.Currency != Currency) throw new InvalidOperationException($"cannot combine {Currency} and {other.Currency}");
    }

    public Money Add(Money other)
    {
        SameCurrency(other);
        return this with { Cents = Cents + other.Cents };
    }

    public Money Subtract(Money other)
    {
        SameCurrency(other);
        return this with { Cents = Cents - other.Cents };
    }

    public Money[] Allocate(int parts)
    {
        if (parts < 1) throw new ArgumentOutOfRangeException(nameof(parts));
        long share = Cents / parts, extra = Cents % parts;
        var result = new Money[parts];
        for (int i = 0; i < parts; i++) result[i] = this with { Cents = share + (i < extra ? 1 : 0) };
        return result;
    }

    public override string ToString()
    {
        string sign = Cents < 0 ? "-" : "";
        long abs = Math.Abs(Cents);
        return $"{sign}{abs / 100}.{abs % 100:D2} {Currency}";
    }
}

unitTests:
Test("parsing", () =>
{
    CheckEq(Money.Parse("12.34 EUR"), new Money(1234, "EUR"));
    CheckEq(Money.Parse("3.5 USD"), new Money(350, "USD"));
    CheckEq(Money.Parse("-5 EUR"), new Money(-500, "EUR"));
    CheckEq(Money.Parse("0.07 GBP").Cents, 7L);
    foreach (string bad in new[] { "12.345 EUR", "12 eur", "EUR 12", "12,50 EUR", "", "1.2.3 EUR" })
        CheckThrows<FormatException>(() => Money.Parse(bad));
});

Test("adding and subtracting", () =>
{
    var a = Money.Parse("12.34 EUR");
    CheckEq(a.Add(Money.Parse("0.66 EUR")).ToString(), "13.00 EUR");
    CheckEq(a.Subtract(Money.Parse("12.39 EUR")).ToString(), "-0.05 EUR");
    CheckThrows<InvalidOperationException>(() => a.Add(Money.Parse("1 USD")));
    CheckEq(a.Cents, 1234L);
});

Test("value equality and with", () =>
{
    var a = new Money(1300, "EUR");
    Check(a == Money.Parse("13 EUR"), "equal values should be ==");
    var b = a with { Currency = "USD" };
    CheckEq(b.ToString(), "13.00 USD");
    CheckEq(a.Currency, "EUR");
});

Test("allocating", () =>
{
    var parts = new Money(1300, "EUR").Allocate(3);
    CheckEq(parts.Select(p => p.ToString()), new[] { "4.34 EUR", "4.33 EUR", "4.33 EUR" });
    CheckEq(new Money(5, "EUR").Allocate(3).Select(p => p.Cents), new[] { 2L, 2L, 1L });
    CheckEq(new Money(100, "EUR").Allocate(1)[0], new Money(100, "EUR"));
    CheckThrows<ArgumentOutOfRangeException>(() => new Money(1, "EUR").Allocate(0));
});

